/**
 * Pakistan admin-1 (province) boundaries for the portal dashboards.
 *
 * Geometry is derived from geoBoundaries gbOpen PAK ADM1 (open data), simplified
 * with Douglas-Peucker at ~1.2km and pre-projected into the SVG viewBox below so
 * province outlines and city markers are guaranteed to line up. Projection is
 * equirectangular with the standard parallel at the country mid-latitude, which
 * keeps Pakistan visually undistorted at this scale.
 */

export interface ProvinceShape {
  /** Canonical province name — matches `branch.region` values. */
  name: string;
  /** Short code used where the full name will not fit. */
  code: string;
  /** Identity colour — every province reads as its own hue across all charts. */
  color: string;
  /** Pale wash of `color`, used for unselected fills and legend chips. */
  tint: string;
  /** SVG path in MAP_VIEWBOX coordinates. */
  path: string;
  /** Label anchor (area centroid of the largest ring). */
  labelX: number;
  labelY: number;
  /**
   * False for provinces too narrow to hold an inline label (ICT, AJK, GB).
   * Those get a leader-line callout in the margin column instead, stacked at
   * `calloutY` so the three of them never collide with each other.
   */
  labelInside: boolean;
  calloutY?: number;
}

export const MAP_VIEWBOX = { width: 1000.0, height: 915.45 };

/**
 * The drawing canvas. Pakistan is taller than it is wide, so a wide dashboard
 * panel would letterbox it with dead space either side; the extra width past
 * MAP_VIEWBOX is the margin column the callout labels live in, which spends
 * that space on legibility instead.
 */
export const MAP_CANVAS = { width: 1300.0, height: 915.45 };
export const MAP_CALLOUT_X = 1020;

const PROJ = {
  minLon: 60.627000,
  maxLon: 78.059000,
  minLat: 23.481000,
  maxLat: 37.250000,
  k: 0.862818,
};

/** Projects a lon/lat pair into MAP_VIEWBOX coordinates. */
export function projectToMap(lng: number, lat: number): { x: number; y: number } {
  const spanX = (PROJ.maxLon - PROJ.minLon) * PROJ.k;
  const spanY = PROJ.maxLat - PROJ.minLat;
  return {
    x: ((lng - PROJ.minLon) * PROJ.k * MAP_VIEWBOX.width) / spanX,
    y: ((PROJ.maxLat - lat) * MAP_VIEWBOX.height) / spanY,
  };
}

/**
 * Algebraic inverse of `projectToMap` — recovers real lon/lat from a point in
 * MAP_VIEWBOX coordinates. Lets us reconstruct real geographic polygons from
 * the pre-projected SVG paths above for use in lon/lat-based map layers
 * (e.g. deck.gl), without sourcing or shipping a second copy of the geodata.
 */
export function unprojectFromMap(x: number, y: number): { lng: number; lat: number } {
  const lng = PROJ.minLon + (x / MAP_VIEWBOX.width) * (PROJ.maxLon - PROJ.minLon);
  const lat = PROJ.maxLat - (y / MAP_VIEWBOX.height) * (PROJ.maxLat - PROJ.minLat);
  return { lng, lat };
}

/** Parses a shape's SVG path into a closed ring of real [lng, lat] points. */
export function provincePolygonLngLat(shape: ProvinceShape): [number, number][] {
  const coords = shape.path.match(/-?\d+\.?\d*/g)?.map(Number) ?? [];
  const points: [number, number][] = [];
  for (let i = 0; i + 1 < coords.length; i += 2) {
    const { lng, lat } = unprojectFromMap(coords[i], coords[i + 1]);
    points.push([lng, lat]);
  }
  return points;
}

/** Unprojects a shape's inline label anchor into real [lng, lat]. */
export function provinceLabelLngLat(shape: ProvinceShape): [number, number] {
  const { lng, lat } = unprojectFromMap(shape.labelX, shape.labelY);
  return [lng, lat];
}

