export const PROVINCE_ORDER: string[] = PROVINCE_SHAPES.map((p) => p.name);

const SHAPE_BY_NAME = new Map(PROVINCE_SHAPES.map((p) => [p.name.toLowerCase(), p]));

/** Alternate spellings seen in branch/region and lead data. */
const PROVINCE_ALIASES: Record<string, string> = {
  "azad kashmir": "Azad Jammu & Kashmir",
  "azad jammu and kashmir": "Azad Jammu & Kashmir",
  ajk: "Azad Jammu & Kashmir",
  kpk: "Khyber Pakhtunkhwa",
  "khyber pakhtoonkhwa": "Khyber Pakhtunkhwa",
  nwfp: "Khyber Pakhtunkhwa",
  islamabad: "Islamabad Capital Territory",
  ict: "Islamabad Capital Territory",
  "capital territory": "Islamabad Capital Territory",
  baluchistan: "Balochistan",
  "gilgit baltistan": "Gilgit-Baltistan",
  gb: "Gilgit-Baltistan",
};

/**
 * Maps free-text region names onto a canonical province. Returns null when the
 * text matches no province, so callers can bucket it as "Other" rather than
 * silently attributing it to the wrong region.
 */
export function normalizeProvince(raw?: string | null): string | null {
  if (!raw) return null;
  const key = raw.toLowerCase().trim();
  if (!key) return null;
  const direct = SHAPE_BY_NAME.get(key);
  if (direct) return direct.name;
  const alias = PROVINCE_ALIASES[key];
  if (alias) return alias;
  for (const shape of PROVINCE_SHAPES) {
    if (key.includes(shape.name.toLowerCase()) || shape.name.toLowerCase().includes(key)) return shape.name;
  }
  return null;
}

export function provinceShape(name?: string | null): ProvinceShape | undefined {
  const canonical = normalizeProvince(name);
  return canonical ? SHAPE_BY_NAME.get(canonical.toLowerCase()) : undefined;
}

/** Identity colour for a province, falling back to a neutral slate. */
export function provinceColor(name?: string | null): string {
  return provinceShape(name)?.color ?? "#94A3B8";
}

